"""Generate the checked-in HTTP contract from FastAPI route and model definitions."""

import sys
from pathlib import Path

import yaml

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from app.main import app  # noqa: E402


def main():
    target = Path(__file__).resolve().parents[3] / "contracts/openapi.yaml"
    target.write_text(
        "# Generated by services/api/scripts/export_openapi.py. Edit Python definitions, then regenerate.\n"
        + yaml.safe_dump(app.openapi(), sort_keys=False, allow_unicode=True),
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
